89	    pub async fn check_for_changes(
90	        &self,
91	        did: &str,
92	    ) -> Result<Vec<UnauthorizedChange>, MonitorError> {
93	        // Fetch current audit log
94	        let current_log_json = self.pds_client.fetch_audit_log(did).await.map_err(|e| {
95	            tracing::warn!(did, error = %e, "failed to fetch audit log, will retry next cycle");
96	            // A background identity check that can't reach the directory fails silently to
97	            // the user. Record the transport case so an exported diagnostics log shows it —
98	            // server verdicts are already captured at the XRPC classification seam, so this
99	            // is gated to transport failures to avoid double-counting.
100	            if matches!(e, crate::pds_client::PdsClientError::NetworkError { .. }) {
101	                crate::diagnostics::record_transport(
102	                    "plc_monitor.fetch_audit_log",
103	                    None,
104	                    "unreachable",
105	                );
106	            }
107	            MonitorError::NetworkError {
108	                message: e.to_string(),
109	            }
110	        })?;
111	
112	        // Parse current log
113	        let current_entries = parse_audit_log(&current_log_json).map_err(|e| {
114	            tracing::warn!(did, error = %e, "failed to parse audit log");
115	            MonitorError::ParseError {
116	                message: e.to_string(),
117	            }
118	        })?;
119	
120	        // Load cached log
121	        let store = IdentityStore;
122	        let cached_entries = match store.get_plc_log(did) {
123	            Ok(Some(cached_json)) => match parse_audit_log(&cached_json) {
124	                Ok(entries) => entries,
125	                Err(e) => {
126	                    tracing::warn!(did, error = %e, "Failed to parse cached audit log, treating as empty");
127	                    vec![]
128	                }
129	            },
130	            Ok(None) => vec![],
131	            Err(e) => {
132	                return Err(MonitorError::IdentityStoreError {
133	                    message: e.to_string(),
134	                });
135	            }
136	        };
137	
138	        // Diff
139	        let new_entries = diff_audit_logs(&cached_entries, &current_entries);
140	
141	        // If no new entries, return
142	        if new_entries.is_empty() {
143	            return Ok(vec![]);
144	        }
145	
146	        // Get device key
147	        let device_key =
148	            store
149	                .get_or_create_device_key(did)
150	                .map_err(|e| MonitorError::IdentityStoreError {
151	                    message: e.to_string(),
152	                })?;
153	        let device_key_uri = DidKeyUri(device_key.key_id);
154	
155	        // Classify each new entry
156	        let mut unauthorized = Vec::new();
157	        for entry in &new_entries {
158	            let op_json =
159	                serde_json::to_string(&entry.operation).map_err(|e| MonitorError::ParseError {
160	                    message: e.to_string(),
161	                })?;
162	
163	            // Try device key first
164	            if verify_plc_operation(&op_json, std::slice::from_ref(&device_key_uri)).is_ok() {
165	                // Authorized — signed by our device key
166	                continue;
167	            }
168	
169	            // Unauthorized — try to identify signing key
170	            let signing_key = identify_signing_key(&op_json, &current_entries, entry);
171	
172	            unauthorized.push(UnauthorizedChange {
173	                cid: entry.cid.clone(),
174	                created_at: entry.created_at.clone(),
175	                signing_key,
176	                operation: entry.operation.clone(),
177	            });
178	        }
179	
180	        // Update cached log — warn on failure but still return detected changes
181	        if let Err(e) = store.store_plc_log(did, &current_log_json) {
182	            tracing::warn!(did, error = %e, "failed to update cached audit log, changes may be re-detected next cycle");
183	        }
184	
185	        Ok(unauthorized)
186	    }
187	}
