189	/// Try each rotation key from the previous operation to identify who signed this entry.
190	fn identify_signing_key(
191	    op_json: &str,
192	    all_entries: &[AuditEntry],
193	    target: &AuditEntry,
194	) -> Option<String> {
195	    // Find the entry just before target in the full log
196	    let prev_entry = all_entries
197	        .iter()
198	        .take_while(|e| e.cid != target.cid)
199	        .last()?;
200	
201	    // Extract rotationKeys from previous operation
202	    let rotation_keys: Vec<String> = match prev_entry.operation.get("rotationKeys") {
203	        Some(v) => serde_json::from_value(v.clone()).unwrap_or_else(|e| {
204	            tracing::debug!(cid = target.cid, error = %e, "failed to parse rotationKeys from previous operation");
205	            vec![]
206	        }),
207	        None => vec![],
208	    };
209	
210	    // Try each key individually
211	    for key in &rotation_keys {
212	        if verify_plc_operation(op_json, &[DidKeyUri(key.clone())]).is_ok() {
213	            return Some(key.clone());
214	        }
215	    }
216	    None
217	}
