261	/// Emit "plc_alert" event to the frontend if any identity has unauthorized changes.
262	fn emit_if_alerts(app_handle: &tauri::AppHandle, statuses: &[IdentityStatus]) {
263	    let has_alerts = statuses.iter().any(|s| !s.unauthorized_changes.is_empty());
264	    if has_alerts {
265	        if let Err(e) = app_handle.emit("plc_alert", statuses) {
266	            tracing::warn!(error = %e, "failed to emit plc_alert event");
267	        }
268	    }
269	}
