5	/**
6	 * An unauthorized PLC operation detected by the monitor.
7	 * Matches UnauthorizedChange struct in plc_monitor.rs with #[serde(rename_all = "camelCase")].
8	 */
9	export interface UnauthorizedChange {
10	  /** CID of the unauthorized operation. */
11	  cid: string;
12	  /** ISO 8601 timestamp when plc.directory accepted the operation. */
13	  createdAt: string;
14	  /** did:key URI of the key that signed this operation, if identified. */
15	  signingKey: string | null;
16	  /** The raw PLC operation JSON for display in alert detail. */
17	  operation: unknown;
18	}
19	
20	/**
21	 * Result of checking a single identity's PLC status.
22	 * Matches IdentityStatus struct in plc_monitor.rs with #[serde(rename_all = "camelCase")].
23	 */
24	export interface IdentityStatus {
25	  did: string;
26	  checkFailed: boolean;
27	  unauthorizedChanges: UnauthorizedChange[];
28	}
29	
30	/**
31	 * Check all managed identities for unauthorized PLC operations.
32	 * Returns a list of IdentityStatus, one per managed DID.
33	 *
34	 * This is the foreground check command — called by the frontend when the app
35	 * becomes visible (visibilitychange event). It supplements the background
36	 * polling timer (interval defined by MONITOR_INTERVAL_SECS) with immediate checks on app foreground.
37	 */
38	export const checkIdentityStatus = (): Promise<IdentityStatus[]> =>
39	  invoke('check_identity_status');
