70	  let rekeyEligible = $state<Map<string, boolean>>(new Map());
71	  let unlisten: UnlistenFn | null = null;
72	  /**
73	   * Set synchronously by `onDestroy`, which runs before this component's async `onMount`
74	   * can finish. Svelte does not treat an async `onMount`'s return value as a cleanup hook,
75	   * so a subscription that resolves after teardown has to disarm itself.
76	   */
77	  let destroyed = false;
78	
79	  // Total unauthorized changes across all identities, for the monitoring banner.
80	  let alertCount = $derived(
81	    Array.from(alertData.values()).reduce((n, changes) => n + changes.length, 0)
82	  );
83	
84	  // Identities this device can no longer sign for. Named in the summary banner so it can
85	  // never read "All identities secure" over a card that says otherwise — and placed ahead of
86	  // the alert banner for the same reason the strips are ordered that way: the override flow
87	  // an alert leads to needs the key that is missing.
88	  let unusableCount = $derived(identities.filter((c) => c.deviceKeyUnusable).length);
89	
90	  // PLC monitoring only watches did:plc identities (a did:web DID has no plc.directory audit log,
91	  // so `plc_monitor` is a no-op for it). Only claim "Watching the public record" when at least one
92	  // did:plc identity is actually being watched; an all-did:web wallet gets an honest note instead.
93	  let watchingPlc = $derived(identities.some((c) => !isDidWeb(c.did)));
94	
95	  function isDeviceKeyRoot(
96	    didDoc: Record<string, unknown>,
97	    deviceKeyId: string
98	  ): boolean | null {
99	    const rotationKeys = didDoc.rotationKeys;
100	    if (!Array.isArray(rotationKeys) || rotationKeys.length === 0) return null;
101	    return rotationKeys[0] === deviceKeyId;
102	  }
103	
104	  async function loadData() {
105	    loading = true;
106	    loadError = null;
107	    const rekeyMap = new Map<string, boolean>();
108	    try {
109	      const dids = await listIdentities();
110	      identities = [];
111	      didDocs.clear();
112	
113	      for (const did of dids) {
114	        try {
115	          // The device key is asked for separately from the doc so a DEVICE_KEY_UNUSABLE
116	          // verdict is caught as the specific, actionable state it is rather than
117	          // collapsing the whole card into the generic degraded branch below.
118	          let deviceKeyUnusable = false;
119	          let keyIdResult = '';
120	          let docResult = await getStoredDidDoc(did);
121	          try {
122	            keyIdResult = await getDeviceKeyId(did);
123	          } catch (e) {
124	            if (isCodedError(e) && e.code === 'DEVICE_KEY_UNUSABLE') {
125	              deviceKeyUnusable = true;
126	            } else {
127	              throw e;
128	            }
129	          }
130	
131	          // Cache self-heal: earlier builds cached DID docs without rotationKeys
132	          // (the W3C shape), which starves the custody badge and hides the migrate
133	          // entry. Re-fetch the PLC data document once and re-store it; on failure
134	          // keep whatever the cache had.
135	          if (docNeedsRotationKeysRefresh(docResult)) {
136	            try {
137	              docResult = await refreshDidDoc(did);
138	            } catch (e) {
139	              console.warn(`DID doc refresh failed for ${did}:`, e);
140	            }
141	          }
142	
143	          const handle = docResult ? extractHandle(docResult) : null;
144	          const pdsUrl = docResult ? extractPdsFromPlcDoc(docResult) : null;
145	          // With no usable key there is no custody claim to make in either direction:
146	          // the badge must not say "root key" (nothing can sign) and must not say
147	          // "not root" (the DID document still lists this device's key at the top).
148	          const deviceKeyIsRoot =
149	            docResult && !deviceKeyUnusable ? isDeviceKeyRoot(docResult, keyIdResult) : null;
150	
151	          if (docResult) {
152	            didDocs.set(did, docResult);
153	          }
154	
155	          // Old-model identities (and interrupted re-keys with a staged set) are offered the
156	          // recovery-key upgrade. The in-progress check resurfaces a re-key whose PLC op already
157	          // landed (so the doc reads as new-model) but whose escrow/Share 1 did not finish.
158	          let eligible = isOldModelRecovery(did, docResult);
159	          if (!eligible && !isDidWeb(did)) {
160	            try {
161	              eligible = await rekeyInProgress(did);
162	            } catch (e) {
163	              console.warn(`Re-key in-progress check failed for ${did}:`, e);
164	            }
165	          }
166	          rekeyMap.set(did, eligible);
167	
168	          identities.push({
169	            did,
170	            handle,
171	            pdsUrl,
172	            deviceKeyIsRoot,
173	            deviceKeyUnusable,
174	          });
175	        } catch (e) {
176	          console.error(`Failed to load identity ${did}:`, e);
177	          // Show degraded card instead of silently dropping the identity
178	          identities.push({
179	            did,
180	            handle: null,
181	            pdsUrl: null,
182	            deviceKeyIsRoot: null,
183	            deviceKeyUnusable: false,
184	          });
185	        }
186	      }
187	    } catch (e) {
188	      console.error('Failed to load identities:', e);
189	      identities = [];
190	      didDocs.clear();
191	      loadError = 'Failed to load identities. Tap refresh to try again.';
192	    } finally {
193	      rekeyEligible = rekeyMap;
194	      loading = false;
195	    }
196	  }
197	
198	  // Index identity statuses by DID, keeping only those with unauthorized changes.
199	  // Shared by the foreground check and the background plc_alert event so both build
200	  // the alert map the same way.
201	  function toAlertMap(statuses: IdentityStatus[]): Map<string, UnauthorizedChange[]> {
202	    const data = new Map<string, UnauthorizedChange[]>();
203	    for (const s of statuses) {
204	      if (s.unauthorizedChanges.length > 0) data.set(s.did, s.unauthorizedChanges);
205	    }
206	    return data;
207	  }
208	
209	  onMount(async () => {
210	    loadData();
211	
212	    checkIdentityStatus()
213	      .then((statuses) => {
214	        alertData = toAlertMap(statuses);
215	      })
216	      .catch((e) => console.warn('Alert check failed:', e));
217	
218	    // Listen for plc_alert events from background monitoring timer
219	    const off = await listen<IdentityStatus[]>('plc_alert', (event) => {
220	      if (!Array.isArray(event.payload)) return;
221	      alertData = toAlertMap(event.payload);
222	    });
223	    // Home unmounts on every step into an identity, so the await above can resolve after
224	    // teardown — by which point `onDestroy` has already run with nothing to release.
225	    if (destroyed) {
226	      off();
227	      return;
228	    }
229	    unlisten = off;
230	  });
231	
232	  onDestroy(() => {
233	    destroyed = true;
234	    unlisten?.();
235	  });
236	
237	  function getBadgeLabel(deviceKeyIsRoot: boolean | null): string {
238	    if (deviceKeyIsRoot === true) return 'Root key';
239	    if (deviceKeyIsRoot === false) return 'Not root';
240	    return 'Unknown';
241	  }
242	
243	  /**
244	   * Which single strip a card shows beneath it. Only one is offered at a time so the
245	   * card never presents two competing calls to action.
246	   *
247	   * `unusable` outranks `alert` deliberately: the alert strip's destination is the
248	   * recovery-override flow, which signs a counter-operation with this device's key —
249	   * the exact key that is gone. Offering it first would send the user into a flow that
250	   * cannot complete. Recovery restores signing, and the alert is still there afterwards.
251	   *
252	   * The share-recovery ceremony is structurally did:plc-only — it works by rotating a
253	   * fresh key into `rotationKeys[0]` via a PLC operation, and a did:web has no rotation
254	   * keys (`start_share_recovery` refuses a non-`did:plc:` identifier outright). A did:web
255	   * whose key is gone therefore gets its own state rather than an offer that dead-ends —
256	   * and rather than nothing, which is the very failure this whole change exists to fix.
257	   */
258	  function activeStrip(
259	    card: IdentityCard,
260	    alerts: UnauthorizedChange[] | undefined,
261	    rekeyOffered: boolean
262	  ): 'unusable' | 'unusable-web' | 'alert' | 'rekey' | null {
263	    if (card.deviceKeyUnusable) {
264	      if (isDidWeb(card.did)) return 'unusable-web';
265	      if (onrecover) return 'unusable';
266	    }
267	    if (alerts?.length) return 'alert';
268	    if (rekeyOffered) return 'rekey';
269	    return null;
270	  }
